// A travelling surface wave for a heightfield (bodies of water). Zero amplitude =
// no wave (all terrain). Mirrors runtime/geometries/Heightfield.ts waveHeight.
pub const HfWave = struct { amp: f32 = 0, len: f32 = 0, speed: f32 = 0, dx: f32 = 1, dz: f32 = 0 };
pub fn hfWaveActive(w: z3d.HfWave) bool {
    return @abs(w.amp) > 1e-4 and w.len > 1e-4;
}
pub fn hfWaveAt(w: z3d.HfWave, x: f32, z: f32, t: f32) f32 {
    const dlen = @sqrt(w.dx * w.dx + w.dz * w.dz);
    const ux = if (dlen > 1e-4) w.dx / dlen else 1.0;
    const uz = if (dlen > 1e-4) w.dz / dlen else 0.0;
    const cycles = (x * ux + z * uz) / w.len + t * w.speed;
    return @sin(cycles * std.math.pi * 2.0) * w.amp;
}

pub fn hfHeightAt(hs: []const f32, cols: usize, rows: usize, ix: i64, iz: i64) f32 {
    const ci: usize = @intCast(std.math.clamp(ix, 0, @as(i64, @intCast(cols)) - 1));
    const cj: usize = @intCast(std.math.clamp(iz, 0, @as(i64, @intCast(rows)) - 1));
    return hs[cj * cols + ci];
}

pub fn hfNormalAt(hs: []const f32, cols: usize, rows: usize, i: usize, j: usize, dx: f32, dz: f32) [3]f32 {
    const ii: i64 = @intCast(i);
    const jj: i64 = @intCast(j);
    const hl = z3d.hfHeightAt(hs, cols, rows, ii - 1, jj);
    const hr = z3d.hfHeightAt(hs, cols, rows, ii + 1, jj);
    const hu = z3d.hfHeightAt(hs, cols, rows, ii, jj - 1);
    const hd = z3d.hfHeightAt(hs, cols, rows, ii, jj + 1);
    var nx = -(hr - hl) / (2.0 * dx);
    var ny: f32 = 1.0;
    var nz = -(hd - hu) / (2.0 * dz);
    const len = @sqrt(nx * nx + ny * ny + nz * nz);
    if (len > 1e-6) {
        nx /= len;
        ny /= len;
        nz /= len;
    }
    return .{ nx, ny, nz };
}

pub fn hfPos(hs: []const f32, cols: usize, i: usize, j: usize, x0: f32, dx: f32, z0: f32, dz: f32) [3]f32 {
    return .{ x0 + @as(f32, @floatFromInt(i)) * dx, hs[j * cols + i], z0 + @as(f32, @floatFromInt(j)) * dz };
}

pub fn hfPush(n: *usize, p: [3]f32, nrm: [3]f32, u: f32, vv: f32) void {
    if (n.* >= z3d.MAX_DYN_VERTS) return;
    z3d.g_hf_scratch[n.*] = .{
        .px = p[0],
        .py = p[1],
        .pz = p[2],
        .noct = pack.octEncodeSnorm16(nrm[0], nrm[1], nrm[2]),
        .u = @floatCast(u),
        .v = @floatCast(vv),
    };
    n.* += 1;
}

pub fn hfSkirt(n: *usize, a: [3]f32, b: [3]f32, c: [3]f32, d: [3]f32, nrm: [3]f32, su: f32) void {
    z3d.hfPush(n, a, nrm, su, 0);
    z3d.hfPush(n, b, nrm, su, 0);
    z3d.hfPush(n, c, nrm, su, 0);
    z3d.hfPush(n, a, nrm, su, 0);
    z3d.hfPush(n, c, nrm, su, 0);
    z3d.hfPush(n, d, nrm, su, 0);
}

// Water-depth UV: when a water mesh ships a per-cell depth grid, the top-surface
// UV.x carries the normalised water column depth (0 at the waterline → 1 at
// HF_DEPTH_NORM metres deep) instead of grid coords, so the water shader can draw
// the deep/shallow gradient + shoreline foam. Non-water fields pass null → grid u.
pub const HF_DEPTH_NORM: f32 = 12.0;
pub fn hfDepthU(depths: ?[]const f32, idx: usize, fallback: f32) f32 {
    if (depths) |d| {
        if (idx < d.len) return std.math.clamp(d[idx] / z3d.HF_DEPTH_NORM, 0.0, 1.0);
    }
    return fallback;
}

/// Build the heightfield mesh into g_hf_scratch; returns the vertex count (0 = bad
/// input). Caller uploads g_hf_scratch[0..count] to the slot.
pub fn hfGen(hs_in: []const f32, cols: usize, rows: usize, width: f32, depth: f32, base: f32, wave: z3d.HfWave, t: f32, depths: ?[]const f32) u32 {
    if (cols < 2 or rows < 2 or hs_in.len < cols * rows) return 0;
    // Water meshes carry a depth grid → top-surface UV.x = normalised depth (so the
    // water shader knows the waterline); skirt walls are "deep" (su=1, no foam).
    const skirt_u: f32 = if (depths != null) 1.0 else 0.0;
    const cf: f32 = @floatFromInt(cols - 1);
    const rf: f32 = @floatFromInt(rows - 1);
    const dx = width / cf;
    const dz = depth / rf;
    const x0 = -width * 0.5;
    const z0 = -depth * 0.5;
    // A wave heightfield ripples its top: build a rippled copy of the grid and
    // bake from that (the rest of the bake is untouched). Cells at/under `base`
    // (outside a disc's footprint) stay flat so the skirt rounds the body off.
    var hs = hs_in;
    if (z3d.hfWaveActive(wave) and cols * rows <= z3d.g_hf_wave_heights.len) {
        var wj: usize = 0;
        while (wj < rows) : (wj += 1) {
            const z = z0 + @as(f32, @floatFromInt(wj)) * dz;
            var wi: usize = 0;
            while (wi < cols) : (wi += 1) {
                const idx = wj * cols + wi;
                const h = hs_in[idx];
                const x = x0 + @as(f32, @floatFromInt(wi)) * dx;
                z3d.g_hf_wave_heights[idx] = if (h > base) h + z3d.hfWaveAt(wave, x, z, t) else h;
            }
        }
        hs = z3d.g_hf_wave_heights[0 .. cols * rows];
    }
    var n: usize = 0;

    // Top surface — wound to face +Y.
    var j: usize = 0;
    while (j + 1 < rows) : (j += 1) {
        var i: usize = 0;
        while (i + 1 < cols) : (i += 1) {
            const pa = z3d.hfPos(hs, cols, i, j, x0, dx, z0, dz);
            const pb = z3d.hfPos(hs, cols, i + 1, j, x0, dx, z0, dz);
            const pc = z3d.hfPos(hs, cols, i + 1, j + 1, x0, dx, z0, dz);
            const pd = z3d.hfPos(hs, cols, i, j + 1, x0, dx, z0, dz);
            const na = z3d.hfNormalAt(hs, cols, rows, i, j, dx, dz);
            const nb = z3d.hfNormalAt(hs, cols, rows, i + 1, j, dx, dz);
            const nc = z3d.hfNormalAt(hs, cols, rows, i + 1, j + 1, dx, dz);
            const nd = z3d.hfNormalAt(hs, cols, rows, i, j + 1, dx, dz);
            // UV.x: grid column by default, OR per-cell normalised water depth when a
            // depth grid is present (water). Each corner keys its own cell, so depth
            // u varies in both i and j (grid u only varied by column).
            const gua = @as(f32, @floatFromInt(i)) / cf;
            const gub = @as(f32, @floatFromInt(i + 1)) / cf;
            const ua = z3d.hfDepthU(depths, j * cols + i, gua);
            const ub = z3d.hfDepthU(depths, j * cols + (i + 1), gub);
            const uc = z3d.hfDepthU(depths, (j + 1) * cols + (i + 1), gub);
            const ud = z3d.hfDepthU(depths, (j + 1) * cols + i, gua);
            const va0 = @as(f32, @floatFromInt(j)) / rf;
            const vb0 = @as(f32, @floatFromInt(j + 1)) / rf;
            z3d.hfPush(&n, pa, na, ua, va0);
            z3d.hfPush(&n, pc, nc, uc, vb0);
            z3d.hfPush(&n, pb, nb, ub, va0);
            z3d.hfPush(&n, pa, na, ua, va0);
            z3d.hfPush(&n, pd, nd, ud, vb0);
            z3d.hfPush(&n, pc, nc, uc, vb0);
        }
    }

    // Perimeter skirt — seal each boundary edge down to `base`, faces outward.
    var si: usize = 0;
    while (si + 1 < cols) : (si += 1) {
        const tn0 = z3d.hfPos(hs, cols, si, 0, x0, dx, z0, dz);
        const tn1 = z3d.hfPos(hs, cols, si + 1, 0, x0, dx, z0, dz);
        if (tn0[1] > base or tn1[1] > base) z3d.hfSkirt(&n, .{ tn1[0], base, tn1[2] }, .{ tn0[0], base, tn0[2] }, tn0, tn1, .{ 0, 0, -1 }, skirt_u);
        const js = rows - 1;
        const ts0 = z3d.hfPos(hs, cols, si, js, x0, dx, z0, dz);
        const ts1 = z3d.hfPos(hs, cols, si + 1, js, x0, dx, z0, dz);
        if (ts0[1] > base or ts1[1] > base) z3d.hfSkirt(&n, .{ ts0[0], base, ts0[2] }, .{ ts1[0], base, ts1[2] }, ts1, ts0, .{ 0, 0, 1 }, skirt_u);
    }
    var sj: usize = 0;
    while (sj + 1 < rows) : (sj += 1) {
        const tw0 = z3d.hfPos(hs, cols, 0, sj, x0, dx, z0, dz);
        const tw1 = z3d.hfPos(hs, cols, 0, sj + 1, x0, dx, z0, dz);
        if (tw0[1] > base or tw1[1] > base) z3d.hfSkirt(&n, .{ tw0[0], base, tw0[2] }, .{ tw1[0], base, tw1[2] }, tw1, tw0, .{ -1, 0, 0 }, skirt_u);
        const ie = cols - 1;
        const te0 = z3d.hfPos(hs, cols, ie, sj, x0, dx, z0, dz);
        const te1 = z3d.hfPos(hs, cols, ie, sj + 1, x0, dx, z0, dz);
        if (te0[1] > base or te1[1] > base) z3d.hfSkirt(&n, .{ te1[0], base, te1[2] }, .{ te0[0], base, te0[2] }, te0, te1, .{ 1, 0, 0 }, skirt_u);
    }

    return @intCast(n);
}

/// Materialize the one immutable 121×121 topology used by formula-painted
/// terrain. A unit-high source grid forces hfGen to include the perimeter skirt:
/// shader-side y=1 vertices fetch real heights, while y=0 skirt bottoms remain
/// at the chunk base. X/Z are unit-spaced sample coordinates and are scaled by
/// the per-chunk cell sizes in the vertex shader.
pub fn initGroundGridTopology(device: *wgpu.Device) void {
    const queue = core.getQueue() orelse return;
    const source = std.heap.c_allocator.alloc(f32, terrain_grid.SAMPLE_COUNT) catch return;
    defer std.heap.c_allocator.free(source);
    @memset(source, 1);
    const span: f32 = @floatFromInt(terrain_grid.SAMPLE_COLS - 1);
    const count = z3d.hfGen(
        source,
        terrain_grid.SAMPLE_COLS,
        terrain_grid.SAMPLE_ROWS,
        span,
        span,
        0,
        .{},
        0,
        null,
    );
    if (count != terrain_grid.TOPOLOGY_VERTEX_COUNT) {
        log.print("[r3d-ground] ERROR: shared terrain topology emitted {d} vertices, expected {d}\n", .{ count, terrain_grid.TOPOLOGY_VERTEX_COUNT });
        return;
    }
    const buffer = device.createBuffer(&.{
        .label = wgpu.StringView.fromSlice("r3d_ground_shared_grid"),
        .size = @as(u64, count) * @sizeOf(z3d.Vertex),
        .usage = wgpu.BufferUsages.vertex | wgpu.BufferUsages.copy_dst,
        .mapped_at_creation = 0,
    }) orelse return;
    bu.writeTypedBuffer(queue, buffer, 0, z3d.Vertex, z3d.g_hf_scratch[0..count]);
    z3d.g_ground_grid_vbuf = buffer;
    z3d.g_ground_grid_vert_count = count;
}

/// Resolve a "~hf~<slotId>~<version>" key: generate the heightfield mesh from the
/// streamed height grid into the reused slot, overwriting on version change. The
/// grid is the same one the collider takes, so render == collide.
pub fn resolveDynamicHeightfield(io: std.Io, queue: *wgpu.Queue, key: []const u8, heights: ?[]const f32, cols: u32, rows: u32, width: f32, depth: f32, base: f32, wave: z3d.HfWave, depths: ?[]const f32) ?z3d.GeoSlice {
    const loc = z3d.dynSlotLocate("~hf~".len, key) orelse return null;
    const s = &z3d.g_dyn_slots[loc.i];
    // A wave heightfield (bodies of water) re-bakes EVERY frame from the host
    // clock so the ripple animates; static fields rebake only on version change.
    const animated = z3d.hfWaveActive(wave);
    if (animated or s.version_hash != loc.ver_hash or s.count == 0) {
        const hs = heights orelse return z3d.existingDyn(s);
        const t: f32 = if (animated) @as(f32, @floatFromInt(@mod(std.Io.Clock.now(.awake, io).toMilliseconds(), 1_000_000))) / 1000.0 else 0;
        const cnt = z3d.hfGen(hs, @intCast(cols), @intCast(rows), width, depth, base, wave, t, depths);
        if (cnt == 0) return z3d.existingDyn(s);
        const buf = z3d.g_retained_vbuf orelse return null;
        // Bump-allocate by the mesh's REAL vert count: a flat chunk is ~30 verts, not a
        // fixed 98k slot — that's what lets hundreds of painted ground chunks coexist.
        // The growth hint is this grid's WORST CASE (every top quad + the perimeter
        // skirt): a chunk being sculpted grows a little every stroke frame, so on its
        // first growth it reserves the ceiling once instead of leaking a region per
        // frame until the tail filled mid-stroke (req_2708).
        const worst: u32 = (cols - 1) * (rows - 1) * 6 + 2 * ((cols - 1) + (rows - 1)) * 6;
        const off = z3d.dynEnsureRegion(s, cnt, worst) orelse return z3d.existingDyn(s);
        bu.writeTypedBuffer(queue, buf, off, z3d.Vertex, z3d.g_hf_scratch[0..cnt]);
        s.version_hash = loc.ver_hash;
        s.count = cnt;
    }
    return z3d.existingDyn(s);
}
